interface.definition:
a!localVariables(
  local!isOldVersion:if(
    a!isNullOrEmpty(ri!nominationView.createdOn),
    false,
    if(
      todatetime(ri!nominationView.createdOn)<#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false)
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
  contents: {
    #"SYSTEM_SYSRULES_columnsLayout"(
      showDividers: true,
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_textField"(
              label: "Anticipated Start Date",
              value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: property(
                  ri!nominationView,
                  "anticipatedStartDate",
                  todate(null)
                )
              ),
              readOnly: true
            ),
            #"SYSTEM_SYSRULES_textField"(
              label: "Anticipated End Date",
              value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: property(
                  ri!nominationView,
                  "anticipatedEndDate",
                  todate(null)
                )
              ),
              readOnly: true
            ),
            #"SYSTEM_SYSRULES_textField"(
              label: "Recommended Group",
              readOnly: true,
              value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: property(
                  ri!nominationView,
                  "dppGroup",
                  tostring(null)
                )
              )
            ),
            #"SYSTEM_SYSRULES_textField"(
              label: "Recommended Group - Other",
              readOnly: true,
              value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: property(
                  ri!nominationView,
                  "dppGroupOtherComment",
                  tostring(null)
                )
              )
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Do you think this person would be a good candidate for a fellowship at the SEC, FASB or GASB?",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                  value: property(
                    ri!nominationView,
                    "isPotentialSec_FasbCandidate",
                    tostring(null)
                  ),
                  isBoolean: true
                )
              ),
              showWhen: if(toboolean(local!isOldVersion)=true,true,false)
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: if(local!isOldVersion=true,"Would you like to nominate the candidate to be an Audit Quality Support Partner upon their return to your BU?"," Would you like to nominate the candidate to be part of the Audit Quality Support Network (AQSN)?"),
              instructions: if(local!isOldVersion=true,"Note: they must be on the partner pipeline for promotion within three years of nomination.",null),
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                  value: property(
                    ri!nominationView,
                    "isAqspNomination",
                    tostring(null)
                  ),
                  isBoolean: true
                )
              )
            )
          },
          showWhen: not(
            contains(
              {
                #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578354",
                #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889",
                #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932"
              },
              property(
                ri!nominationView,
                "statusId",
                tointeger(null)
              )
            )
          )
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_textField"(
              label: "Primary Industry",
              readOnly: true,
              value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: property(
                  ri!nominationView,
                  "industry",
                  tostring(null)
                )
              )
            ),
            #"SYSTEM_SYSRULES_textField"(
              label: "Primary Industry - Other",
              readOnly: true,
              value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: property(
                  ri!nominationView,
                  "primaryIndustryOther",
                  tostring(null)
                )
              )
            )
          }
        )
      }
    )
  }
)
)
